window.futvizVista("tabla-esperada","<div class=\"rx-mount\" data-rx=\"tabla_esperada\" data-rx-id=\"tabla-esperada\" style=\"min-height:640px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"tabla-esperada\"]={\"id\":\"tabla-esperada\",\"titulo\":\"Tabla real vs. esperada\",\"bajada\":\"Puntos reales contra los que val\u00edan las ocasiones de cada equipo, por liga y temporada.\",\"pregunta\":\"\u00bfQui\u00e9n est\u00e1 en el lugar que merece?\",\"tabla\":\"tabla-esperada\",\"queMirar\":\"Compara los puntos reales de cada equipo con los que val\u00edan sus ocasiones, partido a partido (xPts). El punto relleno son los puntos reales y el anillo, los esperados, y la l\u00ednea que los une es la diferencia.\\nLa l\u00ednea va en azul si el equipo sum\u00f3 m\u00e1s de lo esperado y en rojo si sum\u00f3 menos. A la derecha aparece el lugar que ocupar\u00eda en la tabla por xPts y cu\u00e1ntos lugares est\u00e1 por encima (+) o por debajo (\u2212).\",\"fuente\":\"Understat\",\"ligas\":[\"Bundesliga\",\"Serie A\",\"Ligue 1\",\"La Liga\",\"Premier League\"],\"ligaInicial\":\"Premier League\",\"temporadaInicial\":\"2025-26\"};</script>");